import { parseImportJson } from '../import/adminImportProvider';
import type { LookupDate } from './lookupContract';

/**
 * Allowlist DSL for untrusted lookup responses. Validation returns a projection that holds only the
 * declared keys, in declaration order, with raw values unchanged, so unknown fields are dropped and
 * projecting a projection is the identity (the fixture recorder relies on this). Wrong types, bound
 * violations, lone surrogates, pattern mismatches and non-plain objects reject the whole response,
 * except inside a lenient object field, whose invalid value is left out instead; a kept value
 * validates again and a left-out one stays absent, so projecting a projection stays the identity.
 */
export class LookupShapeError extends Error {
    constructor() { super('METADATA_LOOKUP_INVALID_RESPONSE'); this.name = 'LookupShapeError'; }
}

type Presence = { nullable?: boolean; optional?: boolean };
export type LookupShape = Presence & (
    | { kind: 'string'; max: number; pattern?: RegExp }
    | { kind: 'integer'; min: number; max: number }
    | { kind: 'boolean' }
    | { kind: 'array'; items: LookupShape; max: number }
    | { kind: 'object'; fields: Readonly<Record<string, LookupShape>> }
    | { kind: 'oneOf'; options: readonly LookupShape[] }
    | { kind: 'date' }
    | { kind: 'lenient'; shape: LookupShape }
);

export const string = (max: number, options: Presence & { pattern?: RegExp } = {}): LookupShape => ({ kind: 'string', max, ...options });
export const integer = (min: number, max: number, options: Presence = {}): LookupShape => ({ kind: 'integer', min, max, ...options });
export const boolean = (options: Presence = {}): LookupShape => ({ kind: 'boolean', ...options });
export const array = (items: LookupShape, max: number, options: Presence = {}): LookupShape => ({ kind: 'array', items, max, ...options });
export const object = (fields: Record<string, LookupShape>, options: Presence = {}): LookupShape => ({ kind: 'object', fields, ...options });
export const oneOf = (...options: LookupShape[]): LookupShape => ({ kind: 'oneOf', options });
/** `''`, `YYYY`, `YYYY-MM` or `YYYY-MM-DD` with a real calendar day; the raw string is kept. */
export const date = (options: Presence = {}): LookupShape => ({ kind: 'date', ...options });
/** An object field whose invalid value (wrong type, over a bound, null, a lone surrogate) is left out instead of rejecting the response; absent is fine. Elsewhere it validates its shape strictly. */
export const lenient = (shape: LookupShape): LookupShape => ({ kind: 'lenient', shape, optional: true });

const loneSurrogate = /\p{Cs}/u;
const invalid = (): never => { throw new LookupShapeError(); };
const isPlainObject = (value: unknown): value is Record<string, unknown> => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
    const prototype = Object.getPrototypeOf(value);
    return prototype === Object.prototype || prototype === null;
};

/** Parses a validated `date()` value; `''` means unknown. */
export const parseLookupDate = (value: unknown): LookupDate | null => {
    if (value === '' || value === null || value === undefined) return null;
    const match = typeof value === 'string' ? /^(\d{4})(?:-(\d{2})(?:-(\d{2}))?)?$/.exec(value) : null;
    if (!match) return invalid();
    const year = Number(match[1]), month = match[2] === undefined ? null : Number(match[2]), day = match[3] === undefined ? null : Number(match[3]);
    if (year < 1 || (month !== null && (month < 1 || month > 12))) return invalid();
    if (day !== null) {
        const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
        if (day < 1 || day > [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month! - 1]) return invalid();
    }
    return { year, month, day };
};

const validate = (shape: LookupShape, value: unknown): unknown => {
    // Outside an object field a lenient shape is its inner shape, null included.
    if (shape.kind === 'lenient') return validate(shape.shape, value);
    if (value === null) return shape.nullable ? null : invalid();
    switch (shape.kind) {
        case 'string':
            if (typeof value !== 'string' || value.length > shape.max || loneSurrogate.test(value)
                || (shape.pattern && !shape.pattern.test(value))) return invalid();
            return value;
        case 'integer':
            if (typeof value !== 'number' || !Number.isSafeInteger(value) || value < shape.min || value > shape.max) return invalid();
            return value;
        case 'boolean':
            return typeof value === 'boolean' ? value : invalid();
        case 'date':
            if (typeof value !== 'string' || value.length > 10) return invalid();
            parseLookupDate(value);
            return value;
        case 'array':
            if (!Array.isArray(value) || value.length > shape.max) return invalid();
            return value.map(item => validate(shape.items, item));
        case 'object': {
            if (!isPlainObject(value)) return invalid();
            const output: Record<string, unknown> = {};
            for (const [key, field] of Object.entries(shape.fields)) {
                const present = Object.prototype.hasOwnProperty.call(value, key) && value[key] !== undefined;
                if (!present) { if (field.optional) continue; return invalid(); }
                if (field.kind === 'lenient') {
                    try { output[key] = validate(field.shape, value[key]); } catch (error) { if (!(error instanceof LookupShapeError)) throw error; }
                    continue;
                }
                output[key] = validate(field, value[key]);
            }
            return output;
        }
        case 'oneOf':
            for (const option of shape.options) {
                try { return validate(option, value); } catch (error) { if (!(error instanceof LookupShapeError)) throw error; }
            }
            return invalid();
    }
};

/** Returns the allowlisted projection of `value`, or throws `LookupShapeError`. */
export const validateLookupShape = <T = unknown>(shape: LookupShape, value: unknown): T => {
    if (value === undefined) return invalid();
    return validate(shape, value) as T;
};

/** Fatal UTF-8 decoding and the complete JSON parser (duplicate keys and depth over 20 rejected). */
export const decodeLookupJson = (bytes: Buffer): unknown => {
    try { return parseImportJson(new TextDecoder('utf-8', { fatal: true }).decode(bytes)); }
    catch { throw new LookupShapeError(); }
};
